```sql
SELECT COUNT(DISTINCT s.student_id) as distinct_students_enrolled;
FROM Students s
JOIN Student_Course_Enrolment ce ON s.student_id = ce.student_id
JOIN Courses c ON ce.course_id = c.course_id;
```

